export function getProductTechnologies(locale: Locale, parent?: string) {
  return PRODUCT_TECHNOLOGIES.filter((item) => !parent || item.parents.some((slug) => slug === parent)).map((item) => ({
    ...item,
    title: item.title[locale], summary: item.summary[locale], principle: item.principle[locale],
    process: item.process.map((step) => step[locale]),
    configurations: item.configurations.map((entry) => ({ title: entry.title[locale], body: entry.body[locale] })),
    selection: item.selection[locale], verification: item.verification[locale],
  }));
}

export function getProductTechnology(slug: string, locale: Locale) {
  return getProductTechnologies(locale).find((item) => item.slug === slug);
}

export const productTechnologyPath = (slug: string) => `/products/technologies/${slug}`;
